/**
 * Outlines the print-shop glyph set from Arimo (`scripts/fonts/arimo/`) and writes
 * `src/print/glyphOutlines.generated.ts`, so print-shop PDFs draw text as paths and carry no fonts.
 *
 *   npm run generate:glyphs   rewrite the generated file
 *   npm run check:glyphs      fail if it is stale (part of `npm run build`)
 *
 * Rerun after changing the font, the glyph set or `src/print/helveticaMetrics.ts`. Glyphs are placed with
 * the Helvetica AFM advances (the widths every layout measures with), so the script fails if any Arimo
 * advance differs from them by more than 0.5/1000 em.
 */
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import opentype from 'opentype.js';
import {helveticaTextWidthPx} from '../src/print/helveticaMetrics.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const FONT_DIR = path.join(ROOT, 'scripts/fonts/arimo');
const OUT_FILE = path.join(ROOT, 'src/print/glyphOutlines.generated.ts');
const OUT_NAME = path.relative(ROOT, OUT_FILE);
const check = process.argv.includes('--check');

/** Printable ASCII plus the few non-ASCII characters print-shop text uses. U+00B7 `·` is left out (Arimo 333, AFM 278). */
const GLYPH_SET = [
    ...Array.from({length: 0x7f - 0x20}, (_, i) => 0x20 + i),
    0xa0, // no-break space
    0xb0, // °
    0xd7, // ×
    0x2013, // –
    0x2014, // —
    0x2019, // ’
    0x201c, // “
    0x201d, // ”
];

const STYLES = {normal: 'Arimo-Regular.ttf', bold: 'Arimo-Bold.ttf'} as const;
const failures: string[] = [];

/** Integer absolute M/L/Q/Z at 1000 units/em, y down from the baseline. */
function outline(glyph: opentype.Glyph, label: string): string {
    const r = (v: number) => {
        const n = Math.round(v);
        return n === 0 ? 0 : n;
    };
    let d = '';
    for (const c of glyph.getPath(0, 0, 1000).commands) {
        if (c.type === 'M' || c.type === 'L') {
            d += `${c.type}${r(c.x)} ${r(c.y)}`;
        } else if (c.type === 'Q') {
            d += `Q${r(c.x1)} ${r(c.y1)} ${r(c.x)} ${r(c.y)}`;
        } else if (c.type === 'Z') {
            d += 'Z';
        } else {
            failures.push(`${label}: unexpected ${c.type} command (expected quadratic TrueType outlines)`);
        }
    }
    return d;
}

const outlines: Record<string, Record<string, string>> = {};
let capHeightEm = 0;
let xHeightEm = 0;
let version = '';
let copyright = '';
for (const [style, file] of Object.entries(STYLES)) {
    const font = opentype.loadSync(path.join(FONT_DIR, file));
    version ||= (font.names.version?.en ?? '').replace(/;.*$/, '').replace(/^Version\s*/, '');
    copyright ||= font.names.copyright?.en ?? '';
    const table: Record<string, string> = {};
    for (const cp of GLYPH_SET) {
        const ch = String.fromCodePoint(cp);
        const label = `${file} U+${cp.toString(16).toUpperCase().padStart(4, '0')}`;
        const glyph = font.charToGlyph(ch);
        if (!glyph || glyph.index === 0) {
            failures.push(`${label}: missing from the font`);
            continue;
        }
        const advance = (glyph.advanceWidth! / font.unitsPerEm) * 1000;
        const afm = helveticaTextWidthPx(ch, 1000, style === 'bold');
        if (Math.abs(advance - afm) > 0.5) {
            failures.push(`${label}: advance ${advance.toFixed(2)} differs from the Helvetica AFM ${afm}`);
        }
        table[ch] = outline(glyph, label);
    }
    outlines[style] = table;
    if (style === 'normal') {
        capHeightEm = font.charToGlyph('H').getBoundingBox().y2 / font.unitsPerEm;
        xHeightEm = font.charToGlyph('x').getBoundingBox().y2 / font.unitsPerEm;
    }
}

if (failures.length > 0) {
    console.error(`Glyph outlines not written:\n  ${failures.join('\n  ')}`);
    process.exit(1);
}

const out = `/*! @license OFL-1.1
 * Glyph outlines from Arimo ${version} (Regular and Bold). ${copyright}
 * Licensed under the SIL Open Font License, Version 1.1 (https://openfontlicense.org); the full licence
 * ships as licenses/Arimo-OFL.txt.
 */
// Generated by scripts/generate-glyph-outlines.ts (npm run generate:glyphs). Do not edit by hand.

/** Cap height of the outlines, in em (from 'H'). */
export const GLYPH_CAP_HEIGHT_EM = ${Number(capHeightEm.toFixed(3))};

/** x-height of the outlines, in em (from 'x'). */
export const GLYPH_X_HEIGHT_EM = ${Number(xHeightEm.toFixed(3))};

/** Integer absolute M/L/Q/Z path data per character at 1000 units/em, y down from the baseline. */
export const GLYPH_OUTLINES: {readonly normal: Readonly<Record<string, string>>; readonly bold: Readonly<Record<string, string>>} = ${JSON.stringify(outlines)};
`;

const current = fs.existsSync(OUT_FILE) ? fs.readFileSync(OUT_FILE, 'utf8').replace(/\r\n/g, '\n') : null;
if (check) {
    if (current !== out) {
        console.error(`${OUT_NAME} is ${current === null ? 'missing' : 'stale'}: run \`npm run generate:glyphs\` and commit the result.`);
        process.exit(1);
    }
    console.log(`${OUT_NAME} is up to date.`);
} else if (current === out) {
    console.log(`${OUT_NAME} unchanged.`);
} else {
    fs.writeFileSync(OUT_FILE, out);
    console.log(`Wrote ${OUT_NAME}: ${GLYPH_SET.length} glyphs × 2 styles, ${(out.length / 1024).toFixed(1)} KB.`);
}
